import csv
ev={}
out=[]
for T in (5,15,60):
    rows=[r for r in csv.DictReader(open(f'data/tk433/es{T}.csv',encoding='utf-8')) if r['роль']=='event']
    ev[T]=rows; out+=rows
    print(T,len(rows))
fn=list(out[0].keys())
with open('docs/findings/pump-v10-events-2026-09.csv','w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fn); w.writeheader(); w.writerows(out)
def idx(rows):
    d={}
    for r in rows: d.setdefault((r['биржа'],r['рынок'],r['инструмент'],r['знак']),[]).append(int(r['peak_min']))
    return d
I={T:idx(ev[T]) for T in ev}
def share(big,small):
    n=m=0
    for k,v in I[big].items():
        for p in v:
            n+=1
            if any(abs(p-q)<=small for q in I[small].get(k,[])): m+=1
    return m,n
for b,s in ((15,5),(60,5),(60,15)):
    print(f'пики T{b} с пиком T{s} в ±{s} мин:',share(b,s),' пики T%d с пиком T%d в ±%d:'%(s,b,s),share(s,b) if False else '')
def rev(small,big):
    n=m=0
    for k,v in I[small].items():
        for p in v:
            n+=1
            if any(abs(p-q)<=small for q in I[big].get(k,[])): m+=1
    return m,n
for s,b in ((5,15),(5,60),(15,60)):
    print(f'пики T{s} с пиком T{b} в ±{s}:',rev(s,b))
E

